/* ==========================================================================
   Console tokens and surfaces (cp): the E2 instrument panel.
   Reuses the rp palette as custom properties, adds one hue per verdict
   band (mirrored in tailwind.config.js as text-cp-* utilities), and keeps
   every interactive target at 44px or taller. Band text color comes from
   the band's tailwind class, never from these rules, so the badge and the
   forecast strip in E3 share one source of color.
   ========================================================================== */

:root {
  --cp-surface: var(--rp-panel);
  --cp-surface-strong: var(--rp-panel-strong);
  --cp-rule: var(--rp-rule);
  --cp-ink: var(--rp-paper);
  --cp-ink-dim: var(--rp-text-dim);
  --cp-ink-faint: var(--rp-text-faint);
  --cp-inset: rgba(7, 12, 24, 0.55);

  --cp-band-critical: #ff6a4d;
  --cp-band-storm: #f4b740;
  --cp-band-watch: #8b7cf6;
  --cp-band-fair: #39c2e0;
  --cp-band-clear: #35d0ae;

  --cp-radius: var(--rp-radius);
}

.cp-shell {
  display: grid;
  gap: var(--rp-s4);
}

.cp-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--rp-s4);
  align-items: start;
}

@media (min-width: 64rem) {
  .cp-grid {
    grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  }
}

/* Panels, eyebrows, titles ------------------------------------------------ */

.cp-panel {
  background: var(--cp-surface);
  border: 1px solid var(--cp-rule);
  border-radius: var(--cp-radius);
  padding: var(--rp-s5);
  min-width: 0;
}

.cp-panel--error {
  border-color: var(--rp-stamp);
  background: var(--rp-stamp-ghost);
}

.cp-panel__head {
  margin-bottom: var(--rp-s3);
}

.cp-eyebrow {
  font-family: var(--rp-font-utility);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--rp-verified);
  margin: 0;
}

.cp-eyebrow--alert {
  color: var(--rp-stamp);
}

.cp-title {
  font-family: var(--rp-font-display);
  font-weight: 700;
  font-size: clamp(1.25rem, 2.2vw, 1.6rem);
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: var(--cp-ink);
  margin: var(--rp-s1) 0 var(--rp-s2);
}

.cp-sub {
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--cp-ink-faint);
  margin: 0;
}

.cp-label {
  display: block;
  font-family: var(--rp-font-utility);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--cp-ink-faint);
}

.cp-hint {
  font-family: var(--rp-font-utility);
  font-size: 0.75rem;
