})

/** Serve the bundled public/data JSON for every relative data fetch. */
function stubBundledData(): void {
  vi.stubGlobal(
    'fetch',
    vi.fn(async (input: unknown) => {
      const name = String(input).split('/').filter(Boolean).pop() ?? ''
