  it('boots the console and exposes the lookup and the presets', async () => {
    stubBundledData()
    const container = await renderShell()
    await until(container, 'Know the customer')

    expect(container.querySelector('#account-lookup')).not.toBeNull()
    expect(container.textContent).toContain('Pick an account')
    for (const preset of ['layoff', 'cost_spike', 'emergency_repair', 'combo']) {
      expect(container.querySelector(`[data-preset="${preset}"]`)).not.toBeNull()
    }
  })

  it('selects an account and plays a preset from the shell', async () => {
    stubBundledData()
    const container = await renderShell()
