const suggestions = useMemo(() => searchAccountIds(ids, query, 8), [ids, query])

function openFirst(): void {
  const first = suggestions[0]
  if (first) {
    selectAccount(first)
  }
}

function handleKeyDown(event: KeyboardEvent<HTMLInputElement>): void {
  if (event.key === 'Enter') {
    event.preventDefault()
    openFirst()
  }
}

